#include <bits/stdc++.h>
using namespace std;
using lint = long long;
using PII = pair<int, int>;

const int DX[4] = {0, 0, 1, -1};
const int DY[4] = {1, -1, 0, 0};

struct MaxFlow {
    struct Edge {
        int to, rev;
        lint cap;
        Edge(int t, int r, lint c) : to(t), rev(r), cap(c) {}
    };

    int N, S, T;
    vector<vector<Edge>> g;
    vector<int> level, iter;
    queue<int> q;

    MaxFlow(int n, int s, int t) : N(n), S(s), T(t) {
        g.resize(n);
        level.resize(n);
        iter.resize(n);
    }

    void add_edge(int u, int v, lint c) {
        g[u].emplace_back(v, g[v].size(), c);
        g[v].emplace_back(u, g[u].size() - 1, 0);
    }

    bool bfs() {
        fill(level.begin(), level.end(), -1);
        level[S] = 0;
        q.push(S);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : g[u]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[T] != -1;
    }

    lint dfs(int u, lint f) {
        if (u == T) return f;
        for (int& i = iter[u]; i < (int)g[u].size(); ++i) {
            auto& e = g[u][i];
            if (e.cap > 0 && level[e.to] == level[u] + 1) {
                lint pushed = dfs(e.to, min(f, e.cap));
                if (pushed > 0) {
                    e.cap -= pushed;
                    g[e.to][e.rev].cap += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    lint flow() {
        lint res = 0;
        while (bfs()) {
            fill(iter.begin(), iter.end(), 0);
            lint f;
            while ((f = dfs(S, 1LL << 60)) > 0) res += f;
        }
        return res;
    }
};

int N, T;
string gridA[15], gridB[15];
int dist[15][15];

bool in_bounds(int x, int y) {
    return x >= 0 && x < N && y >= 0 && y < N && gridA[x][y] != 'Y' && gridA[x][y] != 'Z';
}

void multi_source_bfs(int sx, int sy) {
    memset(dist, -1, sizeof(dist));
    queue<PII> qu;
    qu.push({sx, sy});
    dist[sx][sy] = 0;
    while (!qu.empty()) {
        auto [x, y] = qu.front(); qu.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + DX[k], ny = y + DY[k];
            if (in_bounds(nx, ny) && dist[nx][ny] == -1) {
                dist[nx][ny] = dist[x][y] + 1;
                qu.push({nx, ny});
            }
        }
    }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (dist[i][j] == -1) dist[i][j] = 1000000000;
}

int memo_dp[65][12][12][12][12];
bool memo_set[65][12][12][12][12];

bool can_reach(int t, int x0, int y0, int x1, int y1) {
    if (dist[x0][y0] < t) return false;
    if (x0 == x1 && y0 == y1) return true;
    if (t >= T) return false;
    if (dist[x0][y0] <= t) return false;
    if (memo_set[t][x0][y0][x1][y1]) return memo_dp[t][x0][y0][x1][y1];
    memo_set[t][x0][y0][x1][y1] = true;
    for (int d = 0; d < 4; ++d) {
        int nx = x0 + DX[d], ny = y0 + DY[d];
        if (nx < 0 || nx >= N || ny < 0 || ny >= N) continue;
        if (gridA[nx][ny] == 'Y' || gridA[nx][ny] == 'Z') continue;
        if (can_reach(t + 1, nx, ny, x1, y1)) {
            memo_dp[t][x0][y0][x1][y1] = 1;
            return true;
        }
    }
    memo_dp[t][x0][y0][x1][y1] = 0;
    return false;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    memset(memo_dp, -1, sizeof(memo_dp));
    cin >> N >> T;
    for (int i = 0; i < N; ++i) cin >> gridA[i];
    for (int i = 0; i < N; ++i) cin >> gridB[i];

    bool found_z = false;
    for (int i = 0; i < N && !found_z; ++i) {
        for (int j = 0; j < N && !found_z; ++j) {
            if (gridA[i][j] == 'Z') {
                multi_source_bfs(i, j);
                found_z = true;
            }
        }
    }

    vector<PII> src, dst;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (gridA[i][j] != 'Z' && gridA[i][j] != 'Y' && gridA[i][j] != '0')
                src.emplace_back(i, j);
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (gridB[i][j] != 'Z' && gridB[i][j] != 'Y' && gridB[i][j] != '0')
                dst.emplace_back(i, j);

    int V = src.size() + dst.size() + 2;
    MaxFlow mf(V, 0, V - 1);

    for (int i = 0; i < src.size(); ++i) {
        lint c = gridA[src[i].first][src[i].second] - '0';
        mf.add_edge(0, i + 1, c);
    }
    for (int i = 0; i < dst.size(); ++i) {
        lint c = gridB[dst[i].first][dst[i].second] - '0';
        mf.add_edge(src.size() + 1 + i, V - 1, c);
    }

    for (int i = 0; i < src.size(); ++i)
        for (int j = 0; j < dst.size(); ++j)
            if (can_reach(0, src[i].first, src[i].second, dst[j].first, dst[j].second))
                mf.add_edge(i + 1, src.size() + 1 + j, 10000000LL);

    cout << mf.flow() << '\n';
    return 0;
}
